  	    "CRLF",
  	    "CTL",
  	    "DIGIT",
  	    "DQUOTE",
  	    "HEXDIG",
  	    "HTAB",
  	    "LF",
  	    "LWSP",
  	    "OCTET",
  	    "SP",
  	    "VCHAR",
  	    "WSP"
